import React, { useEffect, useState } from 'react'
import image1 from './Contact Us.jpg'
import Aos from 'aos'
import 'aos/dist/aos.css'

const Contact = () => {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        mobile: '',
        message: ''
    });

    useEffect(() => {
        Aos.init({ duration: 500 });
    }, [])

    const handleSubmit = async (e) => {
        e.preventDefault();
        const response = await fetch('https://formspree.io/f/mjvqpbgg', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                Name: formData.name,
                Email: formData.email,
                Number: formData.mobile,
                Message: formData.message
            })
        });
        if (response.ok) {
            alert('Message sent successfully!');
            setFormData({ name: '', email: '', mobile: '', message: '' });
        }
    };

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    return (
        <>
            <style>{`
                .modern-input {
                    background: transparent;
                    border: none;
                    border-bottom: 2px solid #ff4500;
                    color: white;
                    padding: 12px 0;
                    width: 100%;
                    font-size: 1rem;
                    outline: none;
                    transition: border-color 0.3s;
                }
                
                .modern-input::placeholder {
                    color: #999;
                }
                
                .modern-input:focus {
                    border-bottom-color: #ff6347;
                }
                
                .modern-textarea {
                    background: transparent;
                    border: 2px solid #ff4500;
                    color: white;
                    padding: 12px;
                    width: 100%;
                    font-size: 1rem;
                    outline: none;
                    resize: vertical;
                    min-height: 120px;
                    border-radius: 4px;
                    transition: border-color 0.3s;
                }
                
                .modern-textarea::placeholder {
                    color: #999;
                }
                
                .modern-textarea:focus {
                    border-color: #ff6347;
                }
                
                .submit-button {
                    background: transparent;
                    border: 2px solid #ff4500;
                    color: white;
                    padding: 15px 60px;
                    font-size: 1.2rem;
                    border-radius: 50px;
                    cursor: pointer;
                    transition: all 0.3s;
                    width: 100%;
                    font-weight: 500;
                }
                
                .submit-button:hover {
                    background: #ff4500;
                    transform: scale(1.02);
                }
                
                .form-group {
                    margin-bottom: 30px;
                }
                
                .row-inputs {
                    display: grid;
                    grid-template-columns: 1fr 1fr;
                    gap: 30px;
                }
                
                @media (max-width: 768px) {
                    .row-inputs {
                        grid-template-columns: 1fr;
                    }
                }
            `}</style>

            <div className='mainContact cont'>
                <div>
                    <h2 className='contact-heading' style={{ color: '#fff', WebkitTextStroke: '0px', textAlign: 'center' }}>
                        Have a Question? Let's Chat
                        <span style={{ color: 'orangered', fontSize: '2.8rem' }}>.</span>
                    </h2>
                    <p style={{color:'#fff', textAlign:'center', marginBottom:'4%'}}>
                        Ready for digital transformation? Partner with Fluencer Digital today!
                    </p>
                </div>
                
                <div className="contact">
                    <div className="firstPart" data-aos="slide-left" style={{ maxWidth: '48%' }}>
                        <img style={{ width: '100%', marginRight: '30px' }} src={image1} alt="" />
                    </div>
                    
                    <div className="SecondPart" data-aos="slide-up" style={{ marginLeft: '25px', flex: '1' }}>
                        <div>
                            <h3 className='h3title' style={{ color: 'white', fontSize: '2.30rem', fontWeight: '400' }}>
                                Schedule a free consultation
                                <span style={{ color: 'orangered', fontSize: '2.8rem' }}>.</span>
                            </h3>
                        </div>
                        
                        <form onSubmit={handleSubmit}>
                            <div className="form-group">
                                <input
                                    type="text"
                                    className="modern-input"
                                    placeholder="Your Name"
                                    name="name"
                                    value={formData.name}
                                    onChange={handleChange}
                                    required
                                />
                            </div>
                            
                            <div className="row-inputs">
                                <div className="form-group">
                                    <input
                                        type="email"
                                        className="modern-input"
                                        placeholder="Your Email Id"
                                        name="email"
                                        value={formData.email}
                                        onChange={handleChange}
                                        required
                                    />
                                </div>
                                
                                <div className="form-group">
                                    <input
                                        type="tel"
                                        className="modern-input"
                                        placeholder="Mobile No."
                                        name="mobile"
                                        value={formData.mobile}
                                        onChange={handleChange}
                                        required
                                    />
                                </div>
                            </div>
                            
                            <div className="form-group">
                                <textarea
                                    className="modern-textarea"
                                    placeholder="Project Details"
                                    name="message"
                                    value={formData.message}
                                    onChange={handleChange}
                                    required
                                ></textarea>
                            </div>
                            
                            <div className="form-group">
                                <button type="submit" className="submit-button">
                                    Submit
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        </>
    )
}

export default Contact